<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#98C379;">rename-command FLUSHDB </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">&quot;&quot;</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">  # 禁用清空库命令</span></span>
